import React from 'react'
import { connect } from 'react-redux'
import { Button, notification, Table, Input, Icon } from 'antd'
import ModalActionGroup from './addActionGroup'
import PermissionChecker from '../../../components/permissionChecker'
import NotificationActions from '../../redux/notifications/actions'
import { getSavedFilters } from '../../../helpers/tableFilterStorage'

const { getMasterData, resetNotificationCore } = NotificationActions
const FILTER_STORAGE_KEY = 'table_action_group_filters'

class TableActionGroup extends React.Component {
  constructor (props) {
    super(props)
    const savedFilters = getSavedFilters(FILTER_STORAGE_KEY)
    this.state = {
      isModalActionGroupOpen: false,
      actionGroups: [],
      loading: true,
      filteredInfo: savedFilters,
      sortedInfo: {}
    }
    this.searchInput = React.createRef()
  }

  componentWillReceiveProps (nextProps) {
    const { getMasterDataStatus, masterData } = nextProps.Notifications
    if (getMasterDataStatus !== '' && getMasterDataStatus === 'success') {
      this.setState({
        actionGroups: masterData.action_groups,
        getMasterDataStatus,
        loading: false
      })
    }
    if (getMasterDataStatus !== '' && getMasterDataStatus !== 'success') {
      notification.error({
        message: 'Error',
        description: getMasterDataStatus
      })
      this.resetState()
      this.setState({ loading: false })
    }
  }

  resetState = () => {
    this.props.resetNotificationCore()
  }

  componentDidMount () {
    this.props.getMasterData()
  }

  addActionGroup = () => {
    this.setState({ isModalActionGroupOpen: true })
  }

  onClose = () => {
    this.setState({ isModalActionGroupOpen: false })
  }

  handleTableChange = (pagination, filters, sorter) => {
    this.setState({
      filteredInfo: filters,
      sortedInfo: sorter
    })
    localStorage.setItem(FILTER_STORAGE_KEY, JSON.stringify(filters))
  }

  getColumnSearchProps = (dataIndex) => {
    const { filteredInfo } = this.state
    return {
      filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters }) => (
        <div style={{ padding: 8 }}>
          <Input
            ref={this.searchInput}
            placeholder={`Search ${dataIndex}`}
            value={selectedKeys?.[0]}
            onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
            onPressEnter={() => confirm()}
            style={{ width: 188, marginBottom: 8, display: 'block' }}
          />
          <div>
            <Button
              type='primary'
              onClick={() => confirm()}
              icon='search'
              size='small'
              style={{ width: 90, marginRight: 8 }}
            >
              Search
            </Button>
            <Button
              onClick={() => clearFilters && clearFilters()}
              size='small'
              style={{ width: 90 }}
            >
              Reset
            </Button>
          </div>
        </div>
      ),
      filterIcon: filtered => (
        <Icon type='search' style={{ color: filtered ? '#1890ff' : undefined }} />
      ),
      filteredValue: filteredInfo[dataIndex] || null,
      onFilter: (value, record) =>
        record[dataIndex]
          ? record[dataIndex].toString().toLowerCase().includes(value.toLowerCase())
          : false,
      onFilterDropdownVisibleChange: visible => {
        if (visible) {
          setTimeout(() => this.searchInput.current?.select(), 100)
        }
      }
    }
  }

  getColumns = () => {
    const { sortedInfo } = this.state
    return [
      {
        title: 'Notification Type',
        dataIndex: 'notification_type',
        key: 'notification_type',
        width: 180,
        sorter: (a, b) => (a.notification_type || '').localeCompare(b.notification_type || ''),
        sortOrder: sortedInfo.columnKey === 'notification_type' && sortedInfo.order,
        ...this.getColumnSearchProps('notification_type')
      },
      {
        title: 'Name',
        dataIndex: 'name',
        key: 'name',
        width: 180,
        sorter: (a, b) => (a.name || '').localeCompare(b.name || ''),
        sortOrder: sortedInfo.columnKey === 'name' && sortedInfo.order,
        ...this.getColumnSearchProps('name')
      },
      {
        title: 'Description',
        dataIndex: 'description',
        key: 'description',
        width: 180,
        sorter: (a, b) => (a.description || '').localeCompare(b.description || ''),
        sortOrder: sortedInfo.columnKey === 'description' && sortedInfo.order,
        ...this.getColumnSearchProps('description')
      },
      {
        title: 'Reply Expected',
        dataIndex: 'reply_expected',
        key: 'reply_expected',
        width: 180,
        sorter: (a, b) => (a.reply_expected || '').localeCompare(b.reply_expected || ''),
        sortOrder: sortedInfo.columnKey === 'reply_expected' && sortedInfo.order,
        ...this.getColumnSearchProps('reply_expected')
      },
      {
        title: 'Created At',
        dataIndex: 'created_at',
        key: 'created_at',
        width: 180,
        sorter: (a, b) => (a.created_at || '').localeCompare(b.created_at || ''),
        sortOrder: sortedInfo.columnKey === 'created_at' && sortedInfo.order,
        ...this.getColumnSearchProps('created_at')
      },
      {
        title: 'Updated At',
        dataIndex: 'updated_at',
        key: 'updated_at',
        width: 180,
        sorter: (a, b) => (a.updated_at || '').localeCompare(b.updated_at || ''),
        sortOrder: sortedInfo.columnKey === 'updated_at' && sortedInfo.order,
        ...this.getColumnSearchProps('updated_at')
      }
    ]
  }

  render () {
    const { permissions } = this.props
    const { actionGroups, loading } = this.state

    return (
      <div>
        <ModalActionGroup
          isOpen={this.state.isModalActionGroupOpen}
          isClose={this.onClose}
        />
        <div style={{ position: 'absolute', right: '0', top: '7px' }}>
          <PermissionChecker
            permissionSetter='ops.add_action_group'
            permissionGetter={permissions}
          >
            <Button type='primary' onClick={this.handleOnAddActionGroup}>
              <i className='fas fa-plus' />
              &nbsp; Add Action Group
            </Button>
          </PermissionChecker>
        </div>
        <div style={{ marginTop: 16 }}>
          <Table
            columns={this.getColumns()}
            dataSource={actionGroups}
            rowKey={record => record.id || record.name}
            loading={loading}
            onChange={this.handleTableChange}
            pagination={{
              showSizeChanger: true,
              showQuickJumper: true,
              showTotal: (total, range) => `${range[0]}-${range[1]} of ${total} items`
            }}
            locale={{
              emptyText: 'Data is empty :('
            }}
            scroll={{ x: 'max-content' }}
          />
        </div>
      </div>
    )
  }
}

export default connect(
  state => ({
    Notifications: state.Notifications
  }),
  {
    getMasterData,
    resetNotificationCore
  }
)(TableActionGroup)
