import React from 'react'
import { connect } from 'react-redux'
import { Divider, Modal, Row, Col, Alert, Button, Icon, message, Upload, Popconfirm, Table, Input, Spin } from 'antd'
import NotificationActions from '../../redux/notifications/actions'
import ReactHtmlParser from 'react-html-parser'
import QueryString from 'query-string'
import QuerySearchBuilder from '../../../helpers/querySearchBuilder'
import { parseSearchParams, serializeSearchParams, saveSearchParams, loadSearchParams } from '../../../helpers/multiColumnSearch'
import PermissionChecker from '../../../components/permissionChecker'

const SEARCH_STORAGE_NAMESPACE = 'templates'

const {
  getTemplates, getTemplateDetail, closeViewBodyHtml,
  filterTemplate, publishTemplate, resetNotificationCore,
  exportNotificationTemplate, importNotificationTemplate, clearTemplateData,
  clearNotificationList, deleteTemplate, getTemplatesPaginated
} = NotificationActions
const dummyRequest = ({ onSuccess }) => {
  onSuccess()
}
const _ = require('lodash')
var fileDownload = require('js-file-download')

class TableTemplates extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      loading: false,
      isClear: false,
      searchTextQuery: {},
      isChange: false,
      loaderPublish: false,
      isPublishModalOpen: false,
      selectCheckBox: [],
      selectCheckBoxTmplId: [],
      selectedRowKeys: [],
      exportlist: {},
      loadInputTemplateView: false,
      importPartialList: false,
      downloadedFile: false,
      importFileData: [],
      dataTemplates: [],
      currentPage: 1,
      perPage: 10,
      totalTemplates: 0
    }
    this.searchInput = React.createRef()
  }

  handleColumnSearch = (selectedKeys, confirm, dataIndex) => {
    if (!selectedKeys[0]) return
    const params = QueryString.parse(this.props.location.search)
    const filterMap = { ...parseSearchParams(params.search, params.search_by), [dataIndex]: selectedKeys[0] }
    const query = {
      page: 1,
      per_page: this.state.perPage,
      ...serializeSearchParams(filterMap),
      ...(params.order_by && { order_by: params.order_by }),
      ...(params.order_dir && { order_dir: params.order_dir })
    }
    this.setState({ currentPage: 1 })
    this.fetchTemplates(query)
    confirm()
  }

  handleColumnReset = (clearFilters, dataIndex) => {
    const params = QueryString.parse(this.props.location.search)
    const filterMap = parseSearchParams(params.search, params.search_by)
    delete filterMap[dataIndex]
    const query = {
      page: 1,
      per_page: this.state.perPage,
      ...serializeSearchParams(filterMap),
      ...(params.order_by && { order_by: params.order_by }),
      ...(params.order_dir && { order_dir: params.order_dir })
    }
    this.setState({ currentPage: 1 })
    this.fetchTemplates(query)
    clearFilters && clearFilters()
  }

  getColumnSearchProps = (dataIndex) => {
    const params = QueryString.parse(this.props.location.search)
    const filterMap = parseSearchParams(params.search, params.search_by)
    const isActive = dataIndex in filterMap
    return {
      filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters }) => (
        <div style={{ padding: 8 }}>
          <Input
            ref={this.searchInput}
            placeholder={`Search ${dataIndex}`}
            value={selectedKeys?.[0]}
            onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
            onPressEnter={() => this.handleColumnSearch(selectedKeys, confirm, dataIndex)}
            style={{ width: 188, marginBottom: 8, display: 'block' }}
          />
          <div>
            <Button
              type='primary'
              onClick={() => this.handleColumnSearch(selectedKeys, confirm, dataIndex)}
              icon='search'
              size='small'
              style={{ width: 90, marginRight: 8 }}
            >
              Search
            </Button>
            <Button
              onClick={() => this.handleColumnReset(clearFilters, dataIndex)}
              size='small'
              style={{ width: 90 }}
            >
              Reset
            </Button>
          </div>
        </div>
      ),
      filterIcon: () => (
        <Icon type='search' style={{ color: isActive ? '#1890ff' : undefined }} />
      ),
      filteredValue: isActive ? [filterMap[dataIndex]] : null,
      onFilterDropdownVisibleChange: visible => {
        if (visible) {
          setTimeout(() => this.searchInput.current?.select(), 100)
        }
      }
    }
  }

  handleTableChange = (pagination, _filters, sorter) => {
    if (!sorter.columnKey) return
    const params = QueryString.parse(this.props.location.search)
    const query = {
      page: 1,
      per_page: this.state.perPage,
      ...(params.search && { search: params.search }),
      ...(params.search_by && { search_by: params.search_by }),
      ...(sorter.order && { order_by: sorter.columnKey }),
      ...(sorter.order && { order_dir: sorter.order === 'ascend' ? 'asc' : 'desc' })
    }
    this.setState({ currentPage: 1 })
    this.fetchTemplates(query)
  }

  onSelectChange = (selectedRowKeys, selectedRows) => {
    const selectCheckBox = selectedRows.map(row => row.pub_tmpl_lang_id)
    const selectCheckBoxTmplId = selectedRows.map(row => row.tmpl_lang_id)
    this.setState({
      selectedRowKeys,
      selectCheckBox,
      selectCheckBoxTmplId
    })
  }

  getColumns = () => {
    const { permissions } = this.props
    const params = QueryString.parse(this.props.location.search)
    const sortOrder = key => (params.order_by === key && params.order_dir)
      ? (params.order_dir === 'asc' ? 'ascend' : 'descend')
      : false

    return [
      {
        title: 'Unique Code',
        dataIndex: 'code',
        key: 'code',
        width: 180,
        sorter: true,
        sortOrder: sortOrder('code'),
        ...this.getColumnSearchProps('code')
      },
      {
        title: 'Description',
        dataIndex: 'description',
        key: 'description',
        width: 180,
        sorter: true,
        sortOrder: sortOrder('description'),
        ...this.getColumnSearchProps('description')
      },
      {
        title: 'Type',
        dataIndex: 'notification_type',
        key: 'notification_type',
        width: 180,
        sorter: true,
        sortOrder: sortOrder('notification_type'),
        ...this.getColumnSearchProps('notification_type')
      },
      {
        title: 'Language',
        dataIndex: 'language_code',
        key: 'language_code',
        width: 180,
        sorter: true,
        sortOrder: sortOrder('language_code'),
        ...this.getColumnSearchProps('language_code')
      },
      {
        title: 'Subject',
        dataIndex: 'subject',
        key: 'subject',
        width: 180,
        sorter: true,
        sortOrder: sortOrder('subject'),
        ...this.getColumnSearchProps('subject')
      },
      {
        title: 'Body',
        key: 'body',
        width: 180,
        render: (_, record) => {
          if (record.tmpl_lang_id !== '') {
            return (
              <PermissionChecker permissionGetter={permissions} permissionSetter='ops.view_detailed_notification_template'>
                <span className='anchor' onClick={() => this.viewBody(record.id, record.tmpl_lang_id)}>
                  View
                </span>
              </PermissionChecker>
            )
          }
          return null
        }
      },
      {
        title: 'Default Language Template',
        dataIndex: 'is_default',
        key: 'is_default',
        width: 180,
        render: (value) => value ? 'Yes' : 'No'
      },
      {
        title: 'Current Publish Version',
        key: 'published_trigger_id',
        width: 180,
        render: (_, record) => {
          if (record.pub_tmpl_lang_id !== null && record.pub_tmpl_lang_id !== '') {
            return (
              <PermissionChecker permissionGetter={permissions} permissionSetter='ops.view_detailed_notification_template'>
                <span className='anchor' onClick={() => this.detailCurrentPublished(record.pub_tmpl_lang_id)}>
                  Detail
                </span>
              </PermissionChecker>
            )
          }
          return null
        }
      },
      {
        title: 'Action',
        key: 'action',
        width: 480,
        render: (_, record) => {
          if (record.tmpl_lang_id !== '') {
            return (
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px', alignItems: 'center' }}>
                <PermissionChecker permissionGetter={permissions} permissionSetter='ops.view_detailed_notification_template'>
                  <span className='anchor' onClick={() => this.view(record.code, record.tmpl_lang_id)}>View</span>
                </PermissionChecker>
                <Divider type='vertical' />
                <PermissionChecker permissionGetter={permissions} permissionSetter='ops.edit_notification_template'>
                  <span className='anchor' onClick={() => this.edit(record.code, record.tmpl_lang_id)}>Edit</span>
                </PermissionChecker>
                <Divider type='vertical' />
                <PermissionChecker permissionGetter={permissions} permissionSetter='ops.edit_notification_template'>
                  <Popconfirm
                    title='Are you sure?'
                    okText='Yes'
                    cancelText='No'
                    onConfirm={() => this.delete([record.tmpl_lang_id])}
                  >
                    <span className='anchor'>Delete</span>
                  </Popconfirm>
                </PermissionChecker>
                {record.dirty === 1 && (
                  <>
                    <Divider type='vertical' />
                    <span className='anchor' onClick={() => this.openPublishModal(record.tmpl_lang_id)}>Publish</span>
                  </>
                )}
                <span style={{ marginLeft: '12px' }}>
                  <i className='fas fa-language' style={{ fontSize: '18px' }} />
                </span>
                <span className='anchor' onClick={() => this.addLanguageTemplate(record.code, record.tmpl_lang_id)}>
                  Add Language Template
                </span>
              </div>
            )
          }
          return null
        }
      },
      {
        title: 'Params',
        dataIndex: 'third_party_template_parameter',
        key: 'params',
        width: 400,
        render: (params) => {
          if (params) {
            return Object.values(params).join(', ')
          }
          return ''
        },
      },
      {
        title: 'Template Id',
        dataIndex: 'third_party_template_id',
        key: 'template_id',
        width: 200
      }
    ]
  }

  getRowClassName = (record) => {
    const publishId = record.pub_tmpl_lang_id || record.published_template_id
    if (record.dirty === 1 && publishId) {
      return 'dirty-version'
    }
    if (record.dirty === 1 && !publishId) {
      return 'unpublish-version'
    }
    return ''
  }

  componentWillReceiveProps (nextProps) {
    const {
      dataDetailTemplate,
      getTemplateDetailStatus,
      publishTemplateStatus,
      exportNotificationTemplatesSuccess,
      exportNotificationTemplatesFailure,
      exportNotificationTemplates,
      importNotificationTemplatesSuccess,
      importNotificationTemplatesFailure,
      importNotificationTemplates,
      templatesPaginatedData,
      templatesPaginatedStatus
    } = nextProps.Notifications
    const { downloadedFile } = this.state

    if (templatesPaginatedStatus === 'success') {
      const rawData = (templatesPaginatedData.data) || []
      const total = (templatesPaginatedData.meta_data && templatesPaginatedData.meta_data.total) || 0
      const modifyData = rawData.map(val => {
        val['color'] = val.dirty === 1 ? '#eee' : '#fff'
        return val
      })
      this.setState({ dataTemplates: modifyData, totalTemplates: total, loading: false })
    } else if (templatesPaginatedStatus !== undefined && templatesPaginatedStatus !== '') {
      this.setState({ loading: false })
    }

    if (getTemplateDetailStatus !== '') {
      this.setState({ dataDetailTemplate, getTemplateDetailStatus, loading: false })
    }
    if (publishTemplateStatus !== '') {
      this.setState({ publishTemplateStatus, loaderPublish: false })
    }
    if (exportNotificationTemplatesSuccess !== '' && exportNotificationTemplates !== undefined) {
      this.setState({ exportlist: exportNotificationTemplates, loading: false })
      if (!downloadedFile) { fileDownload(JSON.stringify(exportNotificationTemplates), 'data.json') }
      this.props.clearNotificationList()
    }
    if (exportNotificationTemplatesFailure !== '' && exportNotificationTemplatesFailure !== undefined) {
      this.setState({ loading: false })
    }

    if (importNotificationTemplatesSuccess !== '' && importNotificationTemplatesSuccess !== undefined) {
      let importlistFailed = _.filter(importNotificationTemplates, (e) => e.success === false)
      importlistFailed = _.map(importlistFailed, object => _.assign({
        'body': object.requested_data.body,
        'description': object.requested_data.description,
        'dirty': 0,
        'is_default': object.requested_data.is_default,
        'language_code': object.requested_data.language_code,
        'notification_type': object.requested_data.notification_type,
        'subject': object.requested_data.subject,
        'pub_tmpl_lang_id': '',
        'tmpl_lang_id': '',
        'color': 'error-row',
        'code': object.requested_data.code
      }))

      const importedPartially = importlistFailed.length > 0

      let importlistSuccess = _.filter(importNotificationTemplates, (e) => e.success === true)
      importlistSuccess = _.map(importlistSuccess, object => _.assign({
        'body': object.requested_data.body,
        'description': object.requested_data.description,
        'dirty': 0,
        'is_default': object.requested_data.is_default,
        'language_code': object.requested_data.language_code,
        'notification_type': object.requested_data.notification_type,
        'subject': object.requested_data.subject,
        'pub_tmpl_lang_id': object.data.pub_tmpl_lang_id,
        'tmpl_lang_id': object.data.tmpl_lang_id,
        'color': 'success-row',
        'code': object.requested_data.code
      }))

      importlistSuccess = importlistSuccess.concat(this.state.dataTemplates)
      importlistFailed = importlistFailed.concat(importlistSuccess)
      this.setState({ dataTemplates: importlistFailed, loading: false, importPartialList: importedPartially })
    }

    if (importNotificationTemplatesFailure !== undefined && importNotificationTemplatesFailure !== '') {
      this.setState({ loading: false })
      message.error(importNotificationTemplatesFailure)
      this.props.clearTemplateData()
    }
  }

  componentDidMount () {
    const { location } = this.props
    const params = QueryString.parse(location.search)
    const persisted = (!params.search || !params.search_by) ? loadSearchParams(SEARCH_STORAGE_NAMESPACE) : null
    const search = params.search || persisted?.search
    const search_by = params.search_by || persisted?.search_by
    const page = Number(params.page) || 1
    const per_page = Number(params.per_page) || 10
    const query = {
      page,
      per_page,
      ...(search && { search }),
      ...(search_by && { search_by }),
      ...(params.order_by && { order_by: params.order_by }),
      ...(params.order_dir && { order_dir: params.order_dir })
    }
    this.setState({ currentPage: page, perPage: per_page })
    this.fetchTemplates(query)
  }

  fetchTemplates = (query) => {
    const { history, location } = this.props
    this.setState({ loading: true })
    saveSearchParams(SEARCH_STORAGE_NAMESPACE, { search: query.search, search_by: query.search_by })
    history.push({ pathname: location.pathname, search: QuerySearchBuilder(query) })
    this.props.getTemplatesPaginated({ query })
  }

  handlePageChange = (page, pageSize) => {
    const { location } = this.props
    const params = QueryString.parse(location.search)
    const query = {
      page,
      per_page: pageSize,
      ...(params.search && { search: params.search }),
      ...(params.search_by && { search_by: params.search_by }),
      ...(params.order_by && { order_by: params.order_by }),
      ...(params.order_dir && { order_dir: params.order_dir })
    }
    this.setState({ currentPage: page, perPage: pageSize }, () => {
      this.fetchTemplates(query)
    })
  }

  onInputChange = (event, identifier) => {
    this.setState({
      searchTextQuery: { [identifier]: event.target.value },
      isChange: true
    })
  }

  onSearch = (e) => {
    e.preventDefault()
    this.setState({ searchTextQuery: {} })
    const { searchTextQuery, dataTemplates } = this.state
    const policyFilter = {}
    const finalFilter = { ...policyFilter, ...searchTextQuery }
    if (Object.values(searchTextQuery).length > 0) {
      this.setState({
        filterCode: false,
        searchTextQuery: finalFilter
      })
      const filterCode = dataTemplates.filter(val => val.code === finalFilter.code)
      this.setState({ dataTemplates: filterCode })
    }
  }

  edit = (id, code) => {
    const { history, location } = this.props
    history.push(`${location.pathname}/template/edit?code=${code}&id=${id}`)
  }

  delete = (rowId) => {
    const { selectCheckBoxTmplId, currentPage, perPage } = this.state
    const toDeleteTemplates = rowId || selectCheckBoxTmplId

    this.props.deleteTemplate(toDeleteTemplates)
    setTimeout(() => {
      const params = QueryString.parse(this.props.location.search)
      this.fetchTemplates({ page: currentPage, per_page: perPage, ...params })
    }, 1000)
  }

  view = (id, code) => {
    const { history, location } = this.props
    history.push(`${location.pathname}/template/view?code=${code}&id=${id}`)
  }

  add = () => {
    const { history, location } = this.props
    history.push(`${location.pathname}/template/add`)
  }

  addLanguageTemplate = (id, code) => {
    const { history, location } = this.props
    history.push(`${location.pathname}/template/add-language?code=${code}&id=${id}`)
  }

  clear = () => {
    const { perPage } = this.state
    this.setState({ dataTemplates: undefined, searchTextQuery: {}, currentPage: 1 })
    this.fetchTemplates({ page: 1, per_page: perPage })
  }

  resetFilters = () => {
    const { perPage } = this.state
    this.setState({ currentPage: 1 })
    this.fetchTemplates({ page: 1, per_page: perPage })
  }

  viewBody = (id, code) => {
    const params = { id, code }
    this.setState({ loading: true })
    this.props.getTemplateDetail(params)
  }

  closeViewBody = () => {
    this.setState({
      dataDetailTemplate: undefined,
      getTemplateDetailStatus: undefined
    })
    this.props.closeViewBodyHtml()
  }

  detailCurrentPublished = publishedId => {
    const { history, location } = this.props
    history.push(`${location.pathname}/template?publishedId=${publishedId}`)
  }

  publish = publishedId => {
    if (publishedId === null) {
      alert('Publish id is empty!')
      return
    }
    this.setState({ loaderPublish: true })
    this.props.publishTemplate({
      id: publishedId,
      published_by: ''
    })
  }

  openPublishModal = publishedId => {
    this.setState({
      isPublishModalOpen: true,
      publishedId
    })
  }

  handleOk = () => {
    const { publishedId } = this.state
    if (publishedId === null) {
      alert('Publish id is empty!')
      return
    }
    this.setState({
      loaderPublish: true,
      isPublishModalOpen: false
    })
    this.props.publishTemplate({
      tmpl_lang_id: publishedId,
      published_by: ''
    })
  }

  handleOnCancel = () => {
    this.setState({
      publishedId: null,
      isPublishModalOpen: false
    })
  }

  onCloseAlert = () => {
    this.props.resetNotificationCore()
    this.setState({ publishTemplateStatus: '' })
  }

  downloadExcel = () => {
    var checkBoxSelected = {}
    checkBoxSelected = [...this.state.selectCheckBox]

    if (checkBoxSelected.length < 1) {
      message.error('select templates to export')
      return
    }

    this.setState({ loading: true })

    let id = '?'
    for (let i = 0; i < checkBoxSelected.length; i++) {
      id = id + 'ids=' + checkBoxSelected[i]
      if (i !== (checkBoxSelected.length - 1)) { id = id + '&' }
    }

    this.props.exportNotificationTemplate(id)
  }

  onCheckChange = e => {
    if (!e.target.checked) {
      var array = [...this.state.selectCheckBox]
      var arrayTmpl = [...this.state.selectCheckBox]
      var index = array.indexOf(e.target.value.pub_tmpl_lang_id)
      array.splice(index, 1)
      var indexTmpl = array.indexOf(e.target.value.tmpl_lang_id)
      arrayTmpl.splice(indexTmpl, 1)
      this.setState({ selectCheckBox: array })
    } else {
      this.setState({ selectCheckBox: [...this.state.selectCheckBox, e.target.value.pub_tmpl_lang_id] })
      this.setState({ selectCheckBoxTmplId: [...this.state.selectCheckBoxTmplId, e.target.value.tmpl_lang_id] })
    }
  }

  async handleChange (info) {
    let files = info.file.originFileObj
    let reader = new FileReader()

    reader.onload = (e) => {
      this.setState({ loadInputTemplateView: true })
      let data = JSON.parse(e.target.result)
      this.props.importNotificationTemplate(data)
    }
    reader.readAsText(files)
  }

  render () {
    const { dataDetailTemplate, getTemplateDetailStatus, selectCheckBox, importPartialList, dataTemplates, selectedRowKeys, currentPage, perPage, totalTemplates } = this.state
    const { permissions, exportNotificationTemplatesSuccess, exportNotificationTemplatesFailure, importNotificationTemplatesSuccess } = this.props
    const urlParams = QueryString.parse(this.props.location.search)
    const hasActiveFilters = !!(urlParams.search || urlParams.search_by || urlParams.order_by || urlParams.order_dir)

    const rowSelection = {
      selectedRowKeys,
      onChange: this.onSelectChange
    }

    return (
      <PermissionChecker permissionSetter='ops.view_notification_template' permissionGetter={permissions}>
        <div className='template-body'>
          {/* Modals */}
          <Modal
            title='Are you sure?'
            visible={this.state.isPublishModalOpen}
            onOk={this.handleOk}
            onCancel={this.handleOnCancel}
            closable={false}
            style={{ textAlign: 'center' }}
            bodyStyle={{ display: 'none' }}
            okText='Yes'
          />
          <Modal
            title='Template'
            visible={getTemplateDetailStatus !== '' && getTemplateDetailStatus === 'success'}
            footer={[]}
            closable
            onCancel={this.closeViewBody}
            maskClosable={false}
            width={'70%'}
          >
            {(getTemplateDetailStatus !== undefined && getTemplateDetailStatus !== 'success') && (
              <Row style={{ marginBottom: '10px' }}>
                <Col>
                  <Alert message={getTemplateDetailStatus} type='error' />
                </Col>
              </Row>
            )}
            <div>
              {ReactHtmlParser(dataDetailTemplate !== undefined ? dataDetailTemplate.body : '')}
            </div>
          </Modal>

          {/* Loading */}
          {(this.state.loading || this.state.loaderPublish) && (
            <div className='loading'>Loading&#8230;</div>
          )}

          {/* Alerts */}
          {(this.state.publishTemplateStatus !== '' && this.state.publishTemplateStatus !== undefined && this.state.publishTemplateStatus !== 'success') && (
            <Row style={{ width: '100%', marginBottom: '10px' }}>
              <Col>
                <Alert message={this.state.publishTemplateStatus} type='error' closable onClose={this.onCloseAlert} />
              </Col>
            </Row>
          )}
          {(this.state.publishTemplateStatus !== '' && this.state.publishTemplateStatus !== undefined && this.state.publishTemplateStatus === 'success') && (
            <Row style={{ width: '100%', marginBottom: '10px' }}>
              <Col>
                <Alert message={this.state.publishTemplateStatus} type='success' closable onClose={this.onCloseAlert} />
              </Col>
            </Row>
          )}
          {exportNotificationTemplatesFailure && (
            <Row style={{ width: '100%', marginBottom: '10px' }}>
              <Col>
                <Alert showIcon closable message='Template for given id not found' type='error' />
              </Col>
            </Row>
          )}
          {exportNotificationTemplatesSuccess && (
            <Row style={{ width: '100%', marginBottom: '10px' }}>
              <Col>
                <Alert showIcon closable message='Success' type='success' />
              </Col>
            </Row>
          )}
          {(importNotificationTemplatesSuccess && !importPartialList) && (
            <Row style={{ width: '100%', marginBottom: '10px' }}>
              <Col>
                <Alert showIcon closable message='Success' type='success' />
              </Col>
            </Row>
          )}
          {importPartialList && (
            <Row style={{ width: '100%', marginBottom: '10px' }}>
              <Col>
                <Alert showIcon closable message='Templates are partially imported' type='warning' />
              </Col>
            </Row>
          )}

          {/* Action Buttons */}
          <div style={{ position: 'absolute', right: '0', top: '7px' }}>
            {hasActiveFilters && (
              <Button style={{ marginRight: '10px' }} onClick={this.resetFilters}>
                <Icon type='close-circle' /> Reset Filters
              </Button>
            )}
            {selectCheckBox.length > 0 && (
              <Popconfirm
                title='Are you sure?'
                okText='Yes'
                cancelText='No'
                onConfirm={() => this.delete()}
              >
                <Button type='danger' style={{ marginRight: '10px' }}>
                  Delete
                </Button>
              </Popconfirm>
            )}
            <Button style={{ marginRight: '10px' }} onClick={this.downloadExcel}>
              Export
            </Button>
            <Upload
              name='avatar'
              showUploadList={false}
              multiple={false}
              customRequest={dummyRequest}
              onChange={file => this.handleChange(file)}
            >
              <Button style={{ marginRight: '10px' }} className='upload-btn'>
                <Icon type='upload' /> Import
              </Button>
            </Upload>
            <PermissionChecker permissionGetter={permissions} permissionSetter='ops.add_notification_template'>
              <Button type='primary' onClick={this.add}>
                <i className='fas fa-plus' />&nbsp; Add template
              </Button>
            </PermissionChecker>
          </div>

          {/* Table */}
          <div style={{ marginTop: 50 }}>
            <Spin spinning={this.state.loading}>
              <Table
                columns={this.getColumns()}
                dataSource={dataTemplates}
                rowKey={record => record.tmpl_lang_id || record.id || record.code}
                rowSelection={rowSelection}
                rowClassName={this.getRowClassName}
                onChange={this.handleTableChange}
                pagination={{
                  current: currentPage,
                  pageSize: perPage,
                  total: totalTemplates,
                  showSizeChanger: true,
                  pageSizeOptions: ['10', '20', '50'],
                  showQuickJumper: true,
                  showTotal: (total, range) => `${range[0]}-${range[1]} of ${total} items`,
                  onChange: this.handlePageChange,
                  onShowSizeChange: this.handlePageChange
                }}
                locale={{
                  emptyText: 'Data is empty :('
                }}
                scroll={{ x: 'max-content' }}
              />
            </Spin>
          </div>
        </div>
      </PermissionChecker>
    )
  }
}

