import React from 'react'
import { connect } from 'react-redux'
import {
  Card,
  Upload,
  Icon,
  Spin,
  message,
  Row,
  Col,
  Select,
  Alert
} from 'antd'
import PropTypes from 'prop-types'

import BulkUploadWrapper from './index.style'
import NotificationActions from '../../../redux/notifications/actions'
import BulkUploadList from './components/BulkUploadList'

const { getNotificationsMasterData, postBulkUploadNotifications } = NotificationActions

const { Dragger } = Upload
const { Option } = Select

class BulkUpload extends React.Component {
  state = {}

  componentDidMount () {
    this.props.getNotificationsMasterData()
  }

  handleSelect (event) {
    this.setState({
      event
    })
  }

  getEventOptions ({ trigger_types: triggerTypes = [] }) {
    return triggerTypes.map(({ name }) => (
      <Option key={name} value={name}>{name}</Option>
    ))
  }

  customRequest = ({ file }) => {
    const { event } = this.state
    const { type } = file
    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(type)) {
      const formData = new FormData()
      formData.append('file', file)
      formData.append('event', event)
      this.props.postBulkUploadNotifications({ body: formData })
    } else {
      message.error('Incorrect file type, please upload only .xlsx/.csv')
    }
  }

  render () {
    const {
      event
    } = this.state
    const {
      masterData,
      notificationsMasterDataLoading,
      postUploadBulkNotificationsLoading,
      postUploadBulkNotificationsError,
      postUploadBulkNotificationsMsg
    } = this.props

    return (
      <BulkUploadWrapper>
        <Card>
          <Spin tip='Uploading...' spinning={!!notificationsMasterDataLoading || !!postUploadBulkNotificationsLoading}>
            <Row>
              <Col xs={{ span: 8 }}>
                {
                  !notificationsMasterDataLoading && (
                    <Select
                      className='fullwidth'
                      showSearch
                      placeholder='Select an operation'
                      onSelect={val => this.handleSelect(val)}
                    >
                      {this.getEventOptions(masterData)}
                    </Select>
                  )
                }
              </Col>
            </Row>
            <Row className='mt-10'>
              {
                !postUploadBulkNotificationsLoading && postUploadBulkNotificationsMsg && (
                  <Alert
                    className='mt-10 text-center'
                    message={postUploadBulkNotificationsMsg}
                    type={postUploadBulkNotificationsError ? 'error' : 'success'}
                  />
                )
              }
              <Dragger
                disabled={!event}
                name='file'
                showUploadList={false}
                multiple={false}
                customRequest={val => this.customRequest(val)}
              >
                {!event ? (
                  <div>
                    <p className='ant-upload-drag-icon'>
                      <Icon type='info-circle' />
                    </p>
                    <p className='ant-upload-text'>Select an event to upload</p>
                  </div>
                ) : (
                  <div>
                    <p className='ant-upload-drag-icon'>
                      <Icon type='inbox' />
                    </p>
                    <p className='ant-upload-text'>Click or drag file to this area to upload</p>
                  </div>
                )}
              </Dragger>
            </Row>
          </Spin>
        </Card>
        <br />
        <Card>
          <BulkUploadList history={this.props.history} />
        </Card>
      </BulkUploadWrapper>
    )
  }
}

BulkUpload.propTypes = {
  masterData: PropTypes.object.isRequired
}

BulkUpload.defaultProps = {
  masterData: {}
}

export default connect(
  state => ({
    masterData: state.Notifications.masterData,
    notificationsMasterDataMsg: state.Notifications.notificationsMasterDataMsg,
    postUploadBulkNotificationsMsg: state.Notifications.postUploadBulkNotificationsMsg,
    notificationsMasterDataLoading: state.Loading.GET_NOTIFICATIONS_MASTER_DATA,
    notificationsMasterDataError: state.Error.GET_NOTIFICATIONS_MASTER_DATA,
    postUploadBulkNotificationsLoading: state.Loading.POST_UPLOAD_BULK_NOTIFICATIONS,
    postUploadBulkNotificationsError: state.Error.POST_UPLOAD_BULK_NOTIFICATIONS
  }),
  {
    getNotificationsMasterData,
    postBulkUploadNotifications
  }
)(BulkUpload)
