import React from 'react'
import { connect } from 'react-redux'
import { Icon, Button, Divider, Alert, Row, Col, Modal, Input, message, Upload, Popconfirm, Table } from 'antd'
import NotificationActions from '../../redux/notifications/actions'
import PolicyActions from '../../../redux/policy/actions'
import QueryString from 'query-string'
import QuerySearchBuilder from '../../../helpers/querySearchBuilder'
import { parseSearchParams, serializeSearchParams, saveSearchParams, loadSearchParams } from '../../../helpers/multiColumnSearch'
import PermissionChecker from '../../../components/permissionChecker'
const { TextArea } = Input
const _ = require('lodash')

const SEARCH_STORAGE_NAMESPACE = 'triggers'

const dummyRequest = ({ file, onSuccess }) => {
  onSuccess()
}
const { getMasterData, getFilterTriggeredData, resetNotificationCore, publish, unpublish, deleteTrigger, getActionGroup, getProduct, exportNotificationTrigger, clearNotificationList, importNotificationTrigger, clearTriggerMessages, getTrigerredData, getTriggerDataNewRequest, resetNotificationsRedux } = NotificationActions
const { getProducts, getPartners } = PolicyActions

const fileDownload = require('js-file-download')

class TableEvents extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      searchTextQuery: {},
      isChange: false,
      loading: true,
      isClear: false,
      loaderPublish: false,
      isPublishModalOpen: false,
      publishedId: null,
      filters: {},
      selectCheckBox: [],
      selectedRowKeys: [],
      exportlist: {},
      loadInputTriggerView: false,
      importPartialList: false,
      downloadedFile: false,
      data: [],
      currentPage: 1,
      perPage: 10,
      totalTriggers: 0
    }
    this.searchInput = React.createRef()
  }

  handleColumnSearch = (selectedKeys, confirm, dataIndex) => {
    if (!selectedKeys[0]) return
    const params = QueryString.parse(this.props.location.search)
    const filterMap = { ...parseSearchParams(params.search, params.search_by), [dataIndex]: selectedKeys[0] }
    const query = {
      page: 1,
      per_page: this.state.perPage,
      ...serializeSearchParams(filterMap),
      ...(params.order_by && { order_by: params.order_by }),
      ...(params.order_dir && { order_dir: params.order_dir })
    }
    this.setState({ currentPage: 1 })
    this.fetchTriggers(query)
    confirm()
  }

  handleColumnReset = (clearFilters, dataIndex) => {
    const params = QueryString.parse(this.props.location.search)
    const filterMap = parseSearchParams(params.search, params.search_by)
    delete filterMap[dataIndex]
    const query = {
      page: 1,
      per_page: this.state.perPage,
      ...serializeSearchParams(filterMap),
      ...(params.order_by && { order_by: params.order_by }),
      ...(params.order_dir && { order_dir: params.order_dir })
    }
    this.setState({ currentPage: 1 })
    this.fetchTriggers(query)
    clearFilters && clearFilters()
  }

  getColumnSearchProps = (dataIndex) => {
    const params = QueryString.parse(this.props.location.search)
    const filterMap = parseSearchParams(params.search, params.search_by)
    const isActive = dataIndex in filterMap
    return {
      filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters }) => (
        <div style={{ padding: 8 }}>
          <Input
            ref={this.searchInput}
            placeholder={`Search ${dataIndex}`}
            value={selectedKeys?.[0]}
            onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
            onPressEnter={() => this.handleColumnSearch(selectedKeys, confirm, dataIndex)}
            style={{ width: 188, marginBottom: 8, display: 'block' }}
          />
          <div>
            <Button
              type='primary'
              onClick={() => this.handleColumnSearch(selectedKeys, confirm, dataIndex)}
              icon='search'
              size='small'
              style={{ width: 90, marginRight: 8 }}
            >
              Search
            </Button>
            <Button
              onClick={() => this.handleColumnReset(clearFilters, dataIndex)}
              size='small'
              style={{ width: 90 }}
            >
              Reset
            </Button>
          </div>
        </div>
      ),
      filterIcon: () => (
        <Icon type='search' style={{ color: isActive ? '#1890ff' : undefined }} />
      ),
      filteredValue: isActive ? [filterMap[dataIndex]] : null,
      onFilterDropdownVisibleChange: visible => {
        if (visible) {
          setTimeout(() => this.searchInput.current?.select(), 100)
        }
      }
    }
  }

  handleTableChange = (_pagination, _filters, sorter) => {
    if (!sorter.columnKey) return
    const params = QueryString.parse(this.props.location.search)
    const query = {
      page: 1,
      per_page: this.state.perPage,
      ...(params.search && { search: params.search }),
      ...(params.search_by && { search_by: params.search_by }),
      ...(sorter.order && { order_by: sorter.columnKey }),
      ...(sorter.order && { order_dir: sorter.order === 'ascend' ? 'asc' : 'desc' })
    }
    this.setState({ currentPage: 1 })
    this.fetchTriggers(query)
  }

  onSelectChange = (selectedRowKeys, selectedRows) => {
    const selectCheckBox = selectedRows.map(row => row.published_trigger_id)
    this.setState({
      selectedRowKeys,
      selectCheckBox
    })
  }

  getColumns = () => {
    const params = QueryString.parse(this.props.location.search)
    const sortOrder = key => (params.order_by === key && params.order_dir)
      ? (params.order_dir === 'asc' ? 'ascend' : 'descend')
      : false

    return [
      {
        title: 'Name',
        dataIndex: 'name',
        key: 'name',
        width: 180,
        sorter: true,
        sortOrder: sortOrder('name'),
        ...this.getColumnSearchProps('name')
      },
      {
        title: 'Event',
        dataIndex: 'trigger_type',
        key: 'trigger_type',
        width: 180,
        sorter: true,
        sortOrder: sortOrder('trigger_type'),
        ...this.getColumnSearchProps('trigger_type')
      },
      {
        title: 'Action Group',
        dataIndex: 'action_group',
        key: 'action_group',
        width: 180,
        sorter: true,
        sortOrder: sortOrder('action_group'),
        ...this.getColumnSearchProps('action_group')
      },
      {
        title: 'Partner',
        dataIndex: 'partner_code',
        key: 'partner_code',
        width: 180,
        sorter: true,
        sortOrder: sortOrder('partner_code'),
        ...this.getColumnSearchProps('partner_code')
      },
      {
        title: 'Product',
        dataIndex: 'product_key',
        key: 'product_key',
        width: 180,
        sorter: true,
        sortOrder: sortOrder('product_key'),
        ...this.getColumnSearchProps('product_key')
      },
      {
        title: 'Expression',
        dataIndex: 'expression',
        key: 'expression',
        width: 180,
        render: (expression) => {
          if (expression && Array.isArray(expression)) {
            return expression.map((value, index) => (
              <p key={index} style={{ margin: 0 }}>{JSON.stringify(value)}</p>
            ))
          }
          return null
        }
      },
      {
        title: 'Template',
        dataIndex: 'template_code',
        key: 'template_code',
        width: 180,
        sorter: true,
        sortOrder: sortOrder('template_code'),
        ...this.getColumnSearchProps('template_code')
      },
      {
        title: 'Current Published Version',
        key: 'published_trigger_id',
        width: 180,
        render: (_, record) => {
          if (record.published_trigger_id !== null) {
            return (
              <span className='anchor' onClick={() => this.detailCurrentPublished(record.published_trigger_id)}>
                Detail
              </span>
            )
          }
          return null
        }
      },
      {
        title: 'Weight',
        dataIndex: 'weight',
        key: 'weight',
        width: 180,
        sorter: true,
        sortOrder: sortOrder('weight')
      },
      {
        title: 'Action',
        key: 'action',
        width: 200,
        render: (_, record) => {
          if (record.id !== undefined && record.id !== '') {
            return (
              <div style={{ width: "100%", display: 'flex', alignItems: 'center' }}>
                <span className='anchor' style={{ whiteSpace: "nowrap" }} onClick={() => this.edit(record.id)}>Edit</span>
                <Divider type='vertical' />
                {record.dirty === 1 ? (
                  <span className='anchor' style={{ whiteSpace: "nowrap" }} onClick={() => this.openPublishModal(record.id)}>Publish</span>
                ) : (
                  <Popconfirm title='Are you sure you want to unpublish?' onConfirm={() => this.unPublishTrigger(record.id)}>
                    <span style={{ whiteSpace: "nowrap" }} className='anchor'>Unpublish</span>
                  </Popconfirm>
                )}
                <Divider type='vertical' />
                <Popconfirm title='Are you sure you want to delete?' onConfirm={() => this.deleteTrigger(record.id)}>
                  <span style={{ whiteSpace: "nowrap" }} className='anchor'>Delete</span>
                </Popconfirm>
              </div>
            )
          }
          return null
        }
      }
    ]
  }

  getRowClassName = (record) => {
    const publishId = record.published_trigger_id || record.published_id
    if (record.dirty === 1 && publishId) {
      return 'dirty-version'
    }
    if (record.dirty === 1 && !publishId) {
      return 'unpublish-version'
    }
    return ''
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      masterData,
      getMasterDataStatus,
      publishStatus,
      getActionGroupStatus,
      exportNotificationTriggerSuccess,
      exportNotificationTriggerFailure,
      exportNotificationsTriggers,
      importNotificationTriggersSuccess,
      importNotificationTriggersFailure,
      importNotificationTriggers,
      getNewTriggerData,
      getNewTriggerDataMessage
    } = nextProps.Notifications

    const { downloadedFile } = this.state

    if (getNewTriggerDataMessage === 'success') {
      const rawData = (getNewTriggerData.data) || []
      const total = (getNewTriggerData.meta_data && getNewTriggerData.meta_data.total) || 0
      const modifyData = rawData.map(val => {
        val.color = val.dirty === 1 ? '#eee' : '#fff'
        return val
      })
      this.setState({ data: modifyData, totalTriggers: total, loading: false })
    } else if (getNewTriggerDataMessage !== undefined && getNewTriggerDataMessage !== '') {
      this.setState({ loading: false })
    }

    const { products, partners } = nextProps.Policy
    if ((partners !== undefined && partners.length > 0) || (products !== undefined && products.length > 0)) {
      this.setState({ partners, products })
    }
    if (getMasterDataStatus !== '') {
      this.setState({ masterData, getMasterDataStatus })
    }
    if (publishStatus !== '') {
      this.setState({ publishStatus, loaderPublish: false })
    }
    if (getActionGroupStatus !== '') {
      this.setState({ getActionGroupStatus })
    }
    if (exportNotificationTriggerSuccess !== '' && exportNotificationsTriggers !== undefined) {
      if (!downloadedFile) { fileDownload(JSON.stringify(exportNotificationsTriggers), 'data.json') } else {
        this.clearNotificationList()
      }
      this.setState({ downloadedFile: !downloadedFile, exportlist: exportNotificationsTriggers, loading: false })
    }
    if (exportNotificationTriggerFailure !== '' && exportNotificationTriggerFailure !== undefined) {
      this.setState({ loading: false })
    }
    if (importNotificationTriggersSuccess !== '' && importNotificationTriggersSuccess !== undefined) {
      let importlistFailed = _.filter(importNotificationTriggers, (e) => e.success === false)
      importlistFailed = _.map(importlistFailed, object => _.assign({
        action_group: object.requested_data.action_group,
        expression: [],
        fixed_recipients_bcc: object.requested_data.fixed_recipients_bcc,
        fixed_recipients_cc: object.requested_data.fixed_recipients_cc,
        name: object.requested_data.name,
        partner_code: object.requested_data.partner_code,
        template_code: object.requested_data.template_code,
        trigger_type: object.requested_data.trigger_type,
        weight: object.requested_data.weight,
        subject: object.requested_data.subject,
        published_trigger_id: '',
        trigger_id: '',
        color: 'error-row'
      }))

      const importedPartially = importlistFailed.length > 0

      let importlistSuccess = _.filter(importNotificationTriggers, (e) => e.success === true)
      importlistSuccess = _.map(importlistSuccess, object => _.assign({
        action_group: object.requested_data.action_group,
        expression: [],
        fixed_recipients_bcc: object.requested_data.fixed_recipients_bcc,
        fixed_recipients_cc: object.requested_data.fixed_recipients_cc,
        name: object.requested_data.name,
        partner_code: object.requested_data.partner_code,
        template_code: object.requested_data.template_code,
        trigger_type: object.requested_data.trigger_type,
        weight: object.requested_data.weight,
        subject: object.requested_data.subject,
        published_trigger_id: object.data.published_trigger_id,
        id: object.data.trigger_id,
        color: 'success-row'
      }))

      importlistSuccess = importlistSuccess.concat(this.state.data)
      importlistFailed = importlistFailed.concat(importlistSuccess)
      this.setState({ data: importlistFailed, loading: false, importPartialList: importedPartially })
    }

    if (importNotificationTriggersFailure !== undefined && importNotificationTriggersFailure !== '') {
      this.setState({ loading: false })
      message.error(importNotificationTriggersFailure)
      this.props.clearTriggerMessages()
    }
  }

  componentDidMount () {
    this.props.getMasterData()
    this.props.getProducts()
    this.props.getPartners()
    const { location } = this.props
    const params = QueryString.parse(location.search)
    const persisted = (!params.search || !params.search_by) ? loadSearchParams(SEARCH_STORAGE_NAMESPACE) : null
    const search = params.search || persisted?.search
    const search_by = params.search_by || persisted?.search_by
    const page = Number(params.page) || 1
    const per_page = Number(params.per_page) || 10
    const query = {
      page,
      per_page,
      ...(search && { search }),
      ...(search_by && { search_by }),
      ...(params.order_by && { order_by: params.order_by }),
      ...(params.order_dir && { order_dir: params.order_dir })
    }
    this.setState({ currentPage: page, perPage: per_page })
    this.fetchTriggers(query)
  }

  fetchTriggers = (query) => {
    const { history, location } = this.props
    this.setState({ loading: true })
    saveSearchParams(SEARCH_STORAGE_NAMESPACE, { search: query.search, search_by: query.search_by })
    history.push({ pathname: location.pathname, search: QuerySearchBuilder(query) })
    this.props.getTriggerDataNewRequest({ query })
  }

  handlePageChange = (page, pageSize) => {
    const { location } = this.props
    const params = QueryString.parse(location.search)
    const query = {
      page,
      per_page: pageSize,
      ...(params.search && { search: params.search }),
      ...(params.search_by && { search_by: params.search_by }),
      ...(params.order_by && { order_by: params.order_by }),
      ...(params.order_dir && { order_dir: params.order_dir })
    }
    this.setState({ currentPage: page, perPage: pageSize }, () => {
      this.fetchTriggers(query)
    })
  }

  resetFilters = () => {
    const { perPage } = this.state
    this.setState({ currentPage: 1 })
    this.fetchTriggers({ page: 1, per_page: perPage })
  }

  fetch = (passParams = {}) => {
    let params = {}
    if (
      'trigger_type' in passParams &&
      'action_group' in passParams &&
      'product_key' in passParams &&
      'partner_code' in passParams
    ) {
      params = { ...params, ...passParams }
      this.setState({ loading: true })
      this.props.getFilterTriggeredData(params)
    }
  }

  detailCurrentPublished = (publishedId) => {
    const { history, location } = this.props
    history.push(`${location.pathname}/trigger?publishedId=${publishedId}`)
  }

  edit = (id) => { // eslint-disable-line
    const { history, location } = this.props
    const query = { id }
    const editQuery = QuerySearchBuilder(query)
    history.push(`${location.pathname}/trigger/edit${editQuery}`)
  }

  handleOnAddTrigger = () => {
    const { history, location } = this.props
    history.push(`${location.pathname}/trigger/add`)
  }

  handleOnAddDefaultTrigger = () => {
    const { history, location } = this.props
    history.push(`${location.pathname}/default-trigger/add`)
  }

  publish = publishedId => {
    if (publishedId === null) {
      alert('Publish id is empty!')
      return
    }
    this.setState({ loaderPublish: true })
    this.props.publish({
      id: publishedId,
      published_by: ''
    })
  }

  handleOnCloseAlert = () => {
    this.props.resetNotificationCore()
    this.setState({ publishStatus: '' })
  }

  clearNotificationList = () => {
    this.props.clearNotificationList()
  }

  openPublishModal = publishedId => {
    this.setState({
      isPublishModalOpen: true,
      publishedId
    })
  }

  handleOk = () => {
    const { publishedId } = this.state
    if (publishedId === null) {
      alert('Publish id is empty!')
      return
    }
    this.setState({
      loaderPublish: true,
      isPublishModalOpen: false
    })
    this.props.publish({
      id: publishedId,
      published_by: ''
    })
    // setTimeout(() => {
    //   this.props.needFreshData()
    // }, 1500)
  }

  handleCancel = () => {
    this.setState({
      publishedId: null,
      isPublishModalOpen: false
    })
  }

  handleOnDownloadExcel = () => {
    let checkBoxSelected = {}
    checkBoxSelected = [...this.state.selectCheckBox]

    if (checkBoxSelected.length < 1) {
      message.error('select Triggers to export')
      return
    }

    this.setState({ loading: true, downloadedFile: false })

    let id = '?'
    for (let i = 0; i < checkBoxSelected.length; i++) {
      id = id + 'ids=' + checkBoxSelected[i]
      if (i !== (checkBoxSelected.length - 1)) { id = id + '&' }
    }
    this.props.exportNotificationTrigger(id)
  }

  async handleChange (info) {
    const files = info.file.originFileObj
    const reader = new FileReader()

    reader.onload = (e) => {
      this.setState({ loadInputTemplateView: true })
      let parsedObject
      try {
        parsedObject = JSON.parse(e.target.result)
        if (
          Array.isArray(parsedObject) && parsedObject.length &&
          parsedObject.every(value => typeof value === 'object' &&
            !Array.isArray(value) && value !== null
          )) {
          this.props.importNotificationTrigger(parsedObject)
        } else throw new Error('invalid data')
      } catch {
        Modal.error({ title: 'Invalid Data' })
      }
    }
    reader.readAsText(files)
  }

  unPublishTrigger = (id) => {
    this.props.unpublish(id)
  }

  deleteTrigger = (id) => {
    this.props.deleteTrigger(id)
  }

  render () {
    const { loadInputTriggerView, importPartialList, selectedRowKeys, currentPage, perPage, totalTriggers } = this.state
    const { permissions, exportNotificationTriggerSuccess, importNotificationTriggersSuccess, exportNotificationTriggerFailure } = this.props
    const urlParams = QueryString.parse(this.props.location.search)
    const hasActiveFilters = !!(urlParams.search || urlParams.search_by || urlParams.order_by || urlParams.order_dir)

    const rowSelection = {
      selectedRowKeys,
      onChange: this.onSelectChange
    }

    return (

      <PermissionChecker permissionSetter='ops.view_notifications_trigger' permissionGetter={permissions}>
        <div className='trigger-event-body'>

          {/* Modals for Triggers Events Starts Here */}
          <Modal
            title='Are you sure?'
            visible={this.state.isPublishModalOpen}
            onOk={this.handleOk}
            onCancel={this.handleCancel}
            closable={false}
            style={{ textAlign: 'center' }}
            bodyStyle={{ display: 'none' }}
            okText='Yes'
          />

          <Modal
            title='Notification Trigger Import'
            visible={loadInputTriggerView}
            footer={[]}
            closable
            onCancel={() => {}}
            markClosable={false}
            width='70%'
          >
            <div>
              <TextArea autosize={{ minRows: 10, maxRows: 20 }} style={{ marginTop: '20px' }} id='textImport' />
              <Button style={{ marginTop: '20px' }} onClick={() => {}}>
                Import
              </Button>
            </div>
          </Modal>
          {/* Modals for Triggers Events End Here */}

          {/* Publish Loader */}
          {
            this.state.loaderPublish && (
              <div className='loading'>Loading&#8230;</div>
            )
          }

          {/* Alerts & Error for Triggers Start Here */}

          {
            (this.state.getActionGroupStatus !== '' && this.state.getActionGroupStatus !== undefined && this.state.getActionGroupStatus !== 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.getActionGroupStatus}
                    type='error'
                    closable
                    onClose={this.handleOnCloseAlert}
                  />
                </Col>
              </Row>
            )
          }
          {
            (this.state.publishStatus !== '' && this.state.publishStatus !== undefined && this.state.publishStatus !== 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.publishStatus}
                    type='error'
                    closable
                    onClose={this.handleOnCloseAlert}
                  />
                </Col>
              </Row>
            )
          }
          {
            (this.state.publishStatus !== '' && this.state.publishStatus !== undefined && this.state.publishStatus === 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.publishStatus}
                    type='success'
                    closable
                    onClose={this.handleOnCloseAlert}
                  />
                </Col>
              </Row>
            )
          }
          {
            (exportNotificationTriggerFailure && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    showIcon
                    closable
                    message='Triggers for given id not found'
                    type='error'
                  />
                </Col>
              </Row>
            ))
          }
          {
            (exportNotificationTriggerSuccess && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    showIcon
                    closable
                    message='Success'
                    type='success'
                  />
                </Col>
              </Row>
            ))
          }
          {
            (importNotificationTriggersSuccess && !importPartialList && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    showIcon
                    closable
                    message='Success'
                    type='success'
                  />
                </Col>
              </Row>
            ))
          }
          {
            (importPartialList && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    showIcon
                    closable
                    message='Triggers are partially imported'
                    type='warning'
                  />
                </Col>
              </Row>
            ))
          }
          {/* Alerts & Error for Triggers End Here */}

          {/* Buttons Start Here (Export ,Import, Default Trigger, Add Trigger) */}
          <div style={{ position: 'absolute', right: '0', top: '7px' }}>
            {hasActiveFilters && (
              <Button style={{ marginRight: '5px' }} onClick={this.resetFilters}>
                <Icon type='close-circle' /> Reset Filters
              </Button>
            )}
            <Button style={{ marginRight: '5px' }} onClick={this.handleOnDownloadExcel}>
              Export
            </Button>
            <Upload
              name='avatar'
              showUploadList={false}
              multiple={false}
              customRequest={dummyRequest}
              onChange={file => this.handleChange(file)}
            >
              <Button
                style={{ marginRight: '10px' }}
                className='upload-btn'
              >
                <Icon type='upload' />
                Import
              </Button>
            </Upload>

            <PermissionChecker
              permissionSetter='ops.add_default_trigger'
              permissionGetter={permissions}
            >
              <Button
                type='primary'
                style={{ marginRight: '5px' }}
                onClick={this.handleOnAddDefaultTrigger}
              >
                <i className='fas fa-plus' />&nbsp;
                Add Default Trigger
              </Button>
            </PermissionChecker>
            <PermissionChecker
              permissionSetter='ops.add_notification_trigger'
              permissionGetter={permissions}
            >
              <Button
                type='primary'
                onClick={this.handleOnAddTrigger}
              >
                <i className='fas fa-plus' />&nbsp;
                Add Trigger
              </Button>
            </PermissionChecker>
          </div>
          {/* Button End Here */}

          {/* Trigger Table Starts Here */}
          <div style={{ marginTop: 16 }}>
            <Table
              columns={this.getColumns()}
              dataSource={this.state.data}
              rowKey={record => record.id || record.name}
              loading={this.state.loading}
              rowSelection={rowSelection}
              rowClassName={this.getRowClassName}
              onChange={this.handleTableChange}
              pagination={{
                current: currentPage,
                pageSize: perPage,
                total: totalTriggers,
                showSizeChanger: true,
                pageSizeOptions: ['10', '20', '50'],
                showQuickJumper: true,
                showTotal: (total, range) => `${range[0]}-${range[1]} of ${total} items`,
                onChange: this.handlePageChange,
                onShowSizeChange: this.handlePageChange
              }}
              locale={{
                emptyText: 'Data is empty :('
              }}
              scroll={{ x: 'max-content' }}
            />
          </div>
          {/* Trigger Table End Here */}
        </div>
      </PermissionChecker>
    )
  }
}

