import React from 'react'
import { connect } from 'react-redux'
import _ from 'lodash'
import { Modal, Form, Select, Button, Input, notification, Row } from 'antd'
import NotificationActions from '../../redux/notifications/actions'
import { AddActionGroupStyle } from './addActionGroup.style'

const FormItem = Form.Item
const Option = Select.Option
const { TextArea } = Input

const { addActionGroup, resetNotificationCore } = NotificationActions

class AddActionGroup extends React.Component {
  state = {
    submitting: false
  }

  componentWillReceiveProps (nextProps) {
    const { addActionGroupStatus } = nextProps.Notifications
    if (addActionGroupStatus !== '' && addActionGroupStatus === 'success') {
      this.setState({ submitting: false })
      notification['success']({ message: addActionGroupStatus })
      this.props.resetNotificationCore()
      this.props.form.resetFields()
      this.props.isClose()
    }
    if (addActionGroupStatus !== '' && addActionGroupStatus !== 'success') {
      this.setState({ submitting: false })
      notification['error']({ message: addActionGroupStatus })
      this.props.resetNotificationCore()
    }
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    e.preventDefault()
    this.setState({ submitting: true })
    const valid = await this.validateForm()
    if (!valid) {
      this.setState({ submitting: false })
      return
    }
    const { form } = this.props
    let data = form.getFieldsValue()
    data = _.pickBy(data, _.identity) // remove undefined or null values
    this.props.addActionGroup(data)
  }

  handleCancel = () => {
    this.props.isClose()
  }

  render () {
    const { isOpen, form, masterData } = this.props
    const { getFieldDecorator } = form
    const notificationTypes = _.get(masterData, 'notification_types', [])
    const appNames = _.get(masterData, 'app_names', [])

    return (
      <Modal
        title='Add Action Group'
        visible={isOpen}
        footer={null}
        closable={false}
        onCancel={this.handleCancel}
      >
        <AddActionGroupStyle>
          <Form onSubmit={this.onSubmit}>
            <FormItem label='Notification Type'>
              {getFieldDecorator('notification_type', {
                rules: [{
                  required: true, message: 'Notification type can not be empty'
                }]
              })(
                <Select
                  showSearch
                  placeholder='Select ...'
                  className='select'
                  filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                >
                  {
                    notificationTypes.map((type, index) => (
                      <Option key={index} value={type}>{type.toUpperCase()}</Option>
                    ))
                  }
                </Select>
              )}
            </FormItem>
            <FormItem label='Name'>
              {getFieldDecorator('name', {
                rules: [{
                  required: true, message: 'Name can not be empty'
                }]
              })(
                <Input />
              )}
            </FormItem>
            <FormItem label='Description'>
              {getFieldDecorator('description', {
                rules: [{
                  required: true, message: 'Description can not be empty'
                }]
              })(
                <TextArea autosize={{ minRows: 2, maxRows: 6 }} />
              )}
            </FormItem>
            <FormItem label='Reply Expected'>
              {getFieldDecorator('reply_expected', {
                rules: [{
                  required: true, message: 'Reply expected can not be empty'
                }]
              })(
                <Select
                  placeholder='Select...'
                >
                  <Option value={1}>Yes</Option>
                  <Option value={0}>No</Option>
                </Select>
              )}
            </FormItem>
            {
              form.getFieldValue('notification_type') === 'mobile_app_push' &&
              <FormItem label='App Name'>
                {getFieldDecorator('app_name', {
                  rules: [
                    { required: true, message: 'Please select App Name' }
                  ]
                })(
                  <Select
                    placeholder='Select App Name...'
                  >
                    {
                      appNames.map((appName) => <Option key={appName} value={appName}>{appName}</Option>)
                    }
                  </Select>
                )}
              </FormItem>
            }
            <Row type='flex' justify='end'>
              <Button key='back' onClick={this.handleCancel}>Cancel</Button>
              <Button
                key='submit'
                type='primary'
                htmlType='submit'
                loading={this.state.submitting}
                className='submit-button'
              >
                Submit
              </Button>
            </Row>
          </Form>
        </AddActionGroupStyle>
      </Modal>
    )
  }
}

const WrappedForm = Form.create({})(AddActionGroup)

export default connect(
  state => ({
    Notifications: state.Notifications,
    masterData: state.Notifications.masterData
  }),
  {
    addActionGroup,
    resetNotificationCore
  }
)(WrappedForm)
