/**
 * Helpers for encoding multiple simultaneous column filters into the
 * `search` / `search_by` query params as quoted, comma-separated lists,
 * e.g. search_by="name","trigger_type" & search="john","renewal".
 *
 * Quoting (mirroring CSV/RFC 4180 style, matching the backend's `csv` based
 * parsing) lets search values safely contain commas.
 */

import { saveFilterParams, loadFilterParams } from './filterPersistence'

const parseQuotedList = (raw) => {
  if (!raw) return []
  const values = []
  let current = ''
  let inQuotes = false

  for (let i = 0; i < raw.length; i++) {
    const char = raw[i]
    if (inQuotes) {
      if (char === '"') {
        if (raw[i + 1] === '"') {
          current += '"'
          i++
        } else {
          inQuotes = false
        }
      } else {
        current += char
      }
    } else if (char === '"') {
      inQuotes = true
    } else if (char === ',') {
      values.push(current)
      current = ''
    } else {
      current += char
    }
  }
  values.push(current)
  return values
}

const serializeQuotedList = (values) => {
  if (!values || !values.length) return ''
  return values.map(value => `"${String(value).replace(/"/g, '""')}"`).join(',')
}

/**
 * Parse the URL's `search` / `search_by` query params into a `{ [column]: value }` map.
 * Mismatched-length input (e.g. a malformed bookmarked URL) is truncated to the shorter list.
 */
export const parseSearchParams = (search, search_by) => {
  const values = parseQuotedList(search)
  const columns = parseQuotedList(search_by)
  const length = Math.min(values.length, columns.length)
  const filterMap = {}
  for (let i = 0; i < length; i++) {
    filterMap[columns[i]] = values[i]
  }
  return filterMap
}

/**
 * Serialize a `{ [column]: value }` map back into `{ search, search_by }` quoted lists.
 * Returns an empty object when the map has no entries, so callers can spread it
 * without emitting empty `search=&search_by=` query params.
 */
export const serializeSearchParams = (filterMap) => {
  const columns = Object.keys(filterMap)
  if (!columns.length) return {}
  const values = columns.map(column => filterMap[column])
  return {
    search: serializeQuotedList(values),
    search_by: serializeQuotedList(columns)
  }
}

/**
 * Persist/restore the current `{ search, search_by }` pair for a table (e.g.
 * 'triggers', 'templates') so the filter survives navigating away (e.g. to a
 * detail/edit/create page) and back. Backed by the generic, page-agnostic
 * `filterPersistence` helper - namespaces are prefixed here so column-search
 * storage doesn't collide with other pages persisting their own filter shapes
 * under the same namespace name.
 */
const namespaceKey = (namespace) => `columnSearch.${namespace}`

export const saveSearchParams = (namespace, { search, search_by } = {}) =>
  saveFilterParams(namespaceKey(namespace), { search, search_by })

export const loadSearchParams = (namespace) => {
  const params = loadFilterParams(namespaceKey(namespace))
  if (!params || !params.search || !params.search_by) return null
  return { search: params.search, search_by: params.search_by }
}
