/**
 * Generic localStorage persistence for page/table filter params, so a filter
 * survives navigating away (e.g. to a detail/edit/create page) and back.
 *
 * Unlike `tableFilterStorage.js` (which stores Ant Design Table's internal
 * `{ column: [values] }` filter state), this stores whatever plain filter
 * params object a page builds for its own fetch/query (e.g. `{ search,
 * search_by }`, `{ filter_by, filter_value }`, etc.) - the shape is up to the
 * caller, this module only handles namespacing, serialization and storage.
 */

const storageKey = (namespace) => `filterPersistence.${namespace}`

/**
 * Persist a filter params object for the given namespace (e.g. a page or table
 * name) to localStorage. Passing an empty object, or one whose values are all
 * falsy, clears the stored value instead.
 */
export const saveFilterParams = (namespace, params = {}) => {
  try {
    const hasValue = Object.values(params).some(Boolean)
    if (!hasValue) {
      window.localStorage.removeItem(storageKey(namespace))
      return
    }
    window.localStorage.setItem(storageKey(namespace), JSON.stringify(params))
  } catch (e) {
    // localStorage may be unavailable (e.g. private browsing) - persistence is best-effort
  }
}

/**
 * Load a previously persisted filter params object for the given namespace.
 * Returns null when nothing is stored, the value is empty, or storage is
 * unavailable/corrupted (in which case the bad entry is also cleared).
 */
export const loadFilterParams = (namespace) => {
  try {
    const raw = window.localStorage.getItem(storageKey(namespace))
    if (!raw) return null
    const parsed = JSON.parse(raw)
    if (!parsed || typeof parsed !== 'object' || !Object.values(parsed).some(Boolean)) return null
    return parsed
  } catch (e) {
    try {
      window.localStorage.removeItem(storageKey(namespace))
    } catch (_e) {
      // ignore - best effort cleanup
    }
    return null
  }
}

/**
 * Clear any persisted filter params for the given namespace.
 */
export const clearFilterParams = (namespace) => {
  try {
    window.localStorage.removeItem(storageKey(namespace))
  } catch (e) {
    // ignore - best effort
  }
}
