import React from 'react'
import { connect } from 'react-redux'
import { Modal, Form, Button, Input, notification } from 'antd'
import NotificationActions from '../../redux/notifications/actions'

const FormItem = Form.Item
const { TextArea } = Input

const { addTriggertype, resetNotificationCore } = NotificationActions

class AddTriggerType extends React.Component {
    state = {
      submitting: false
    }
    componentWillReceiveProps (nextProps) {
      const { addTriggerTypeStatus } = nextProps.Notifications
      if (addTriggerTypeStatus !== '' && addTriggerTypeStatus === 'success') {
        this.setState({ submitting: false })
        notification['success']({ message: addTriggerTypeStatus })
        this.props.resetNotificationCore()
        this.props.form.resetFields()
        this.props.isClose()
      }
      if (addTriggerTypeStatus !== '' && addTriggerTypeStatus !== 'success') {
        this.setState({ submitting: false })
        notification['error']({ message: addTriggerTypeStatus })
        this.props.resetNotificationCore()
      }
    }
    async validateForm () {
      return new Promise((resolve) => {
        this.props.form.validateFields((error, values) => {
          resolve(!error)
        })
      })
    }
    onSubmit = async e => {
      e.preventDefault()
      this.setState({ submitting: true })
      const valid = await this.validateForm()
      if (!valid) {
        this.setState({ submitting: false })
        return
      }
      const { form } = this.props
      let data = form.getFieldsValue()
      this.props.addTriggertype(data)
    }
    handleCancel = () => {
      this.props.isClose()
    }
    render () {
      const { isOpen, form } = this.props
      const { getFieldDecorator } = form
      return (
        <div>
          <Modal
            title='Add trigger type'
            visible={isOpen}
            footer={[]}
            closable={false}
            onCancel={this.handleCancel}
          >
            <Form onSubmit={this.onSubmit}>
              <label className='custom-label'>Name</label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('name', {
                  rules: [{
                    required: true, message: 'Name can not be empty'
                  }]
                })(
                  <Input />
                )}
              </FormItem>
              <label className='custom-label'>Description</label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('description', {
                  rules: [{
                    required: true, message: 'Description can not be empty'
                  }]
                })(
                  <TextArea autosize={{ minRows: 2, maxRows: 6 }} />
                )}
              </FormItem>
              <div style={{ textAlign: 'right' }}>
                <Button key='back' onClick={this.handleCancel}>Cancel</Button>
                <Button
                  key='submit'
                  type='primary'
                  htmlType='submit'
                  loading={this.state.submitting}
                  style={{ marginLeft: '10px' }}
                >
                                                        Submit
                </Button>
              </div>
            </Form>
          </Modal>
        </div>
      )
    }
}

const WrappedForm = Form.create({})(AddTriggerType)

export default connect(
  state => ({
    Notifications: state.Notifications
  }),
  { addTriggertype, resetNotificationCore }
)(WrappedForm)
