/**
 * Helper functions for Ant Design Table filter persistence with localStorage
 * Handles migration from old AG-Grid filter format to Ant Design format
 */

/**
 * Get saved filters from localStorage with automatic migration from AG-Grid format
 * @param {string} storageKey - The localStorage key to read from
 * @returns {object} - Filters in Ant Design format
 *
 * AG-Grid format: {"column":{"type":"contains","filter":"value","filterType":"text"}}
 * Ant Design format: {"column":["value"]}
 */
export const getSavedFilters = (storageKey) => {
  try {
    const saved = localStorage.getItem(storageKey)
    if (!saved) return {}

    const parsed = JSON.parse(saved)
    const migrated = {}
    let needsMigration = false

    for (const key in parsed) {
      const value = parsed[key]
      if (value && typeof value === 'object' && !Array.isArray(value) && value.filter !== undefined) {
        // Old AG-Grid format detected - convert to Ant Design format
        migrated[key] = [value.filter]
        needsMigration = true
      } else if (Array.isArray(value)) {
        // Already in correct Ant Design format
        migrated[key] = value
      } else {
        migrated[key] = value
      }
    }

    if (needsMigration) {
      localStorage.setItem(storageKey, JSON.stringify(migrated))
    }

    return migrated
  } catch {
    // If anything fails, clear the corrupted filter and return empty
    localStorage.removeItem(storageKey)
    return {}
  }
}

/**
 * Save filters to localStorage
 * @param {string} storageKey - The localStorage key to save to
 * @param {object} filters - Filters object from Ant Design Table onChange
 */
export const saveFilters = (storageKey, filters) => {
  localStorage.setItem(storageKey, JSON.stringify(filters))
}

/**
 * Clear filters from localStorage
 * @param {string} storageKey - The localStorage key to clear
 */
export const clearFilters = (storageKey) => {
  localStorage.removeItem(storageKey)
}
