import React from 'react'
import { Row, Col, Tabs } from 'antd'
import { connect } from 'react-redux'
import Cookies from 'universal-cookie'

import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import TableEvents from './tableEvents'
import TableTemplates from './tableTemplates'
import TableActionGroup from './tableActionGroup'
import TableTriggerType from './tableTriggerType'
import BulkUpload from './BulkUpload'

const cookies = new Cookies()
const TabPane = Tabs.TabPane

class Notifications extends React.Component {
    state = {
      defaultActiveKey: cookies.get('eventTab') !== undefined ? cookies.get('eventTab') : 'triggers'
    }

    callback = val => {
      cookies.set('eventTab', val, { path: '/' })
      this.setState({ defaultActiveKey: val })
      this.props.history.push({ pathname: this.props.location.pathname, search: '' })
    }
    render () {
      const { permissions } = this.props

      return (
        <LayoutContentWrapper>
          <LayoutContent>
            <Row>
              <Col>
                <Tabs defaultActiveKey={this.state.defaultActiveKey} onChange={this.callback} className='notification-tabs' destroyInactiveTabPane>
                  <TabPane tab='Triggers' key='triggers' value={'default'}>
                    <TableEvents
                      {...this.props}
                      permissions={permissions}
                    />
                  </TabPane>

                  <TabPane tab='Templates' key='template'>
                    <TableTemplates
                      {...this.props}
                      permissionsList={permissions}
                    />
                  </TabPane>
                  <TabPane tab='Action group' key='Action group'>
                    <TableActionGroup
                      permissions={permissions}
                    />
                  </TabPane>
                  <TabPane tab='Trigger type' key='Trigger type'>
                    <TableTriggerType
                      permissions={permissions}
                    />
                  </TabPane>
                  {permissions.includes('ops.view_notifications_bulk_upload') && (
                    <TabPane tab='Bulk Upload' key='Bulk Upload'>
                      <BulkUpload history={this.props.history} />
                    </TabPane>
                  )}
                </Tabs>
              </Col>
            </Row>
          </LayoutContent>
        </LayoutContentWrapper>
      )
    }
}

export default connect(
  state => ({
    permissions: state.Auth.permissions
  }),
  {}
)(Notifications)
