import React from 'react'
import { connect } from 'react-redux'
import {
  Table
} from 'antd'
import PropTypes from 'prop-types'

import BulkUploadListWrapper from './index.style'
import NotificationActions from '../../../../../redux/notifications/actions'

const { getBulkNotificationsFiles } = NotificationActions

class BulkUploadList extends React.Component {
  state = {}
  fileColumns = [
    {
      title: 'ID',
      dataIndex: 'id',
      key: 'id'
    }, {
      title: 'File Url',
      dataIndex: 'file_url',
      key: 'file_url',
      render: (val) => (<a href={val}>Download File</a>)
    }, {
      title: 'Reference ID',
      dataIndex: 'reference_id',
      key: 'reference_id'
    }, {
      title: 'Action',
      dataIndex: 'reference_id',
      key: 'reference_id',
      render: (val) => (
        <span onClick={() => this.traceNotification(val)}>
          View Notifications Sent
        </span>
      ),
      align: 'center'
    }
  ]

  componentDidMount () {
    this.props.getBulkNotificationsFiles()
  }

  traceNotification (notificationId) {
    this.props.history.push(`/notifications/${notificationId}`)
  }

  render () {
    const {
      bulkNotificationsFiles
    } = this.props
    return (
      <BulkUploadListWrapper>
        <Table
          scroll={{ x: true }}
          pagination={{
            pageSize: 1000
          }}
          columns={this.fileColumns}
          dataSource={bulkNotificationsFiles}
        />
      </BulkUploadListWrapper>
    )
  }
}

BulkUploadList.propTypes = {
  getBulkNotificationsFiles: PropTypes.array.isRequired
}

BulkUploadList.defaultProps = {
  getBulkNotificationsFiles: []
}

export default connect(
  state => ({
    bulkNotificationsFiles: state.Notifications.bulkNotificationsFiles,
    bulkNotificationsFilesMsg: state.Notifications.bulkNotificationsFilesMsg,
    getBulkNotificationsFilesLoading: state.Loading.GET_BULK_NOTIFICATIONS_FILES,
    getBulkNotificationsFilesError: state.Error.GET_BULK_NOTIFICATIONS_FILES
  }),
  {
    getBulkNotificationsFiles
  }
)(BulkUploadList)
